SOURCE_FILE = '常用函数扩展增强类库-Ver-003.md'
SOURCE_FEATURES = ['var ', 'for ', 'while ', '=>']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.']
ORIGINAL_JAVASCRIPT = '/*\n * @Project: 官方扩展增强类库\n * @Version: Ver 0.0.3\n * @Author: RedSword <redsword@gmail.com>\n * @Description:收集整理常用增强函数\n * @Date: 2021-05-06 11:02:29\n * @LastEditors: RedSword\n * @LastEditTime: 2021-09-07 11:35:52\n * @Copyright:: Copyright © 2020 FMZ Quant\n * 代码规范参考: https://github.com/fex-team/styleguide/blob/master/javascript.md\n */\n\n/* jshint esversion: 6 */\n/**\n * @Title: 转北京时间\n * @description: 将托管者所在服务器时间转为北京时间\n * @param {time} localtime 所在时间\n * @return {time} 北京时间\n * @example\n *  var localDate = $.ToBJTime(new Date());\n *  Log(localDate)  //Thu May 06 2021 11:19:45 GMT+0000\n *  Log(localDate.getTime())    //1620299985696\n */\n$.ToBJTime = function (localDate) {\n    return new Date(localDate.getTime() + localDate.getTimezoneOffset() * 60000 + 3600000 * 8);\n};\n\n/**\n * 将日期格式化成指定格式的字符串\n * @param date 要格式化的日期，不传时默认当前时间，也可以是一个时间戳\n * @param fmt 目标字符串格式，支持的字符有：y,M,d,q,w,H,h,m,S，默认：yyyy-MM-dd HH:mm:ss\n * @returns 返回格式化后的日期字符串\n */\n$.FormatDate = function (date, fmt) {\n    date = !date ? new Date() : date;\n    date = typeof date === "number" ? new Date(date) : date;\n    fmt = fmt || "yyyy-MM-dd HH:mm:ss";\n    var obj = {\n        y: date.getFullYear(), // 年份，注意必须用getFullYear\n        M: date.getMonth() + 1, // 月份，注意是从0-11\n        d: date.getDate(), // 日期\n        q: Math.floor((date.getMonth() + 3) / 3), // 季度\n        w: date.getDay(), // 星期，注意是0-6\n        H: date.getHours(), // 24小时制\n        h: date.getHours() % 12 == 0 ? 12 : date.getHours() % 12, // 12小时制\n        m: date.getMinutes(), // 分钟\n        s: date.getSeconds(), // 秒\n        S: date.getMilliseconds(), // 毫秒\n    };\n    var week = ["天", "一", "二", "三", "四", "五", "六"];\n    for (var i in obj) {\n        fmt = fmt.replace(new RegExp(i + "+", "g"), function (m) {\n            var val = obj[i] + "";\n            if (i == "w") return (m.length > 2 ? "星期" : "周") + week[val];\n            for (var j = 0, len = val.length; j < m.length - len; j++) val = "0" + val;\n            return m.length == 1 ? val : val.substring(val.length - m.length);\n        });\n    }\n    return fmt;\n};\n/**\n * @Title: 获取永久缓存\n * @description:当缓存不存在时,写入缓存,如果存在就返回数据,一般记录初始价格使用\n * @param {string} key 唯一标示\n * @param {*} data 要保存的数据\n * @return {*}\n *\n */\n$.ForeverCache = function (key, data) {\n    key = "ForeverCache" + key;\n    var getDate = _G(key);\n    if (getDate == null) {\n        _G(key, data);\n        return data;\n    }\n    return getDate;\n};\n\n/**\n * @title: 当天缓存\n * @description:获取当天的缓存,每天北京时间0点0分重置数据\n * @param {string} key 唯一标示\n * @param {*} data 要保存的数据\n * @return {*}\n */\n$.TodayCache = function (key, data) {\n    key = "TodayCache" + key;\n    var today = $.ToBJTime(new Date()).getDate();\n    if (_G("TodayCacheToday_" + key) !== today) {\n        _G("TodayCacheToday_" + key, today);\n        _G(key, data);\n        return data;\n    } else {\n        return _G(key);\n    }\n};\n\n/**\n * @title: 定时执行函数\n * @description: 指定时间间隔,来执行函数\n * @param {int} second 间隔时间,为秒\n * @param {string} key 标识\n * @param {function} fun 要执行的函数\n * @return {*} 定时执行函数的结果\n * @example\n * //每60秒执行一次nowTime()函数\n * Log($.ExecuteFuncForTime(60,"myTime",nowTime))\n */\n$.ExecuteFuncForTime = function (second, key, fun) {\n    var endSecond = second * 1000;\n    var nowTime = new Date().getTime();\n    if (_G("funcForTime_" + key) == null || nowTime - _G("funcForTime_" + key) > endSecond) {\n        var data = fun();\n        _G("funcForTime_" + key, nowTime);\n        _G(key, data);\n        return data;\n    } else {\n        return _G(key);\n    }\n};\n\n/**\n * @title: Object排序\n * @description:根据指定的标识符,对Object进行排序\n * @param {object} obj 要排序的对象\n * @param {string} key 标识符\n * @return {object}\n * @example\n *  var obj = { aa: { f: 2 }, bb: { f: 1 }, cc: { f: 3 } };\n *\tLog(sortobjkey(obj,\'f\')) //{"cc":{"f":3},"aa":{"f":2},"bb":{"f":1}}\n */\n$.SortObjectKey = function (obj, key) {\n    var o = {};\n    Object.keys(obj)\n        .map(function (k, i) {\n            return [k, obj[k]];\n        })\n        .sort(function (a, b) {\n            k = key;\n            if (a[1][k] > b[1][k]) return -1;\n            if (a[1][k] < b[1][k]) return 1;\n            return 0;\n        })\n        .forEach(function (a) {\n            o[a[0]] = a[1];\n        });\n    return o;\n};\n\n/**\n * @title:策略运行时间\n * @description:记录第一次运行时间并计算已经运行的时间数\n * @return {object} 对象\n * @example\n * Log($.RunTime())\n * //{"RunSeconds":18170,"NowUnix":1622821609901,"NowTime":"2021-06-04 23:46:49","FormatTime":"运行时间: 0 天 5 时 2 分 50 秒","StartTime":"2021-06-04 18:43:59"}\n */\n$.RunTime = function () {\n    var startTime = new Date($.ForeverCache("startTime", new Date()));\n    var between = $.TimeBetween(startTime, new Date());\n    var timestamp = parseInt(UnixNano() / 1000000);\n    let week = $.GetWeek($.ToBJTime(new Date()));\n    return {\n        RunSeconds: parseInt((timestamp - startTime.getTime()) / 1000), //运行秒数\n        NowUnix: timestamp, //当间时间戳\n        NowTime: _D($.ToBJTime(new Date())), //当前时间\n        NowYear: week.year,\n        NowMonth: week.month,\n        NowDay: week.day,\n        NowWeek: week.week,\n        FormatTime: "运行时间: " + between.days + " 天 " + between.hours + " 时 " + between.minutes + " 分 " + between.seconds + " 秒", //格式化后的运行时间\n        StartTime: _D($.ToBJTime(startTime)), //开始时间\n        StartUnix: $.ForeverCache("StartUnix", timestamp),\n    };\n};\n\n$.TimeBetween = function (startDate, endDate) {\n    let delta = Math.abs(endDate - startDate) / 1000;\n    const isNegative = startDate > endDate ? -1 : 1;\n    return [\n        ["days", 24 * 60 * 60],\n        ["hours", 60 * 60],\n        ["minutes", 60],\n        ["seconds", 1],\n    ].reduce((acc, [key, value]) => ((acc[key] = Math.floor(delta / value) * isNegative), (delta -= acc[key] * isNegative * value), acc), {});\n};\n$.GetAnalyze = function (totalAssets) {\n    var sqlDB;\n    try {\n        sqlDB = DBExec("select * from profit");\n    } catch (error) {\n        return false;\n    }\n\n    var profits = sqlDB.values;\n    if (profits.length == 0) {\n        return {\n            totalAssets: totalAssets,\n            yearDays: 0,\n            totalReturns: 0,\n            annualizedReturns: 0,\n            sharpeRatio: 0,\n            volatility: 0,\n            nowDrawdown: 0,\n            maxDrawdown: 0,\n            maxDrawdownTime: 0,\n            maxAssetsTime: 0,\n            maxDrawdownStartTime: 0,\n            winningRate: 0,\n            nowDrawdownFormat: {\n                days: 0,\n                hours: 0,\n                minutes: 0,\n                seconds: 0,\n            },\n            maxDrawdownFormat: {\n                days: 0,\n                hours: 0,\n                minutes: 0,\n                seconds: 0,\n            },\n        };\n    }\n    var yearDays = 365;\n    // force by days\n    var period = 86400000;\n    //Log(profits[0], profits[10]);\n    var ts = profits[0][3];\n    var te = profits[profits.length - 1][3];\n\n    var freeProfit = 0.03; // 0.04\n    var yearRange = yearDays * 86400000;\n    var totalReturns = profits[profits.length - 1][1] / totalAssets;\n    var annualizedReturns = (totalReturns * yearRange) / (te - ts);\n\n    // MaxDrawDown\n    var maxDrawdown = 0;\n    var maxAssets = totalAssets;\n    var maxAssetsTime = 0;\n    var maxDrawdownTime = 0;\n    var maxDrawdownStartTime = 0;\n    var winningRate = 0;\n    var winningResult = 0;\n    //var nowDrawdown = 0;\n\n    for (var i = 0; i < profits.length; i++) {\n        if (i == 0) {\n            if (profits[i][1] > 0) {\n                winningResult++;\n            }\n        } else {\n            if (profits[i][1] > profits[i - 1][1]) {\n                winningResult++;\n            }\n        }\n        if (profits[i][1] + totalAssets > maxAssets) {\n            maxAssets = profits[i][1] + totalAssets;\n            maxAssetsTime = profits[i][3];\n        }\n        if (maxAssets > 0) {\n            var drawDown = 1 - (profits[i][1] + totalAssets) / maxAssets;\n            if (drawDown > maxDrawdown) {\n                maxDrawdown = drawDown;\n                maxDrawdownTime = profits[i][3];\n                maxDrawdownStartTime = maxAssetsTime;\n            }\n        }\n    }\n    if (profits.length > 0) {\n        winningRate = winningResult / profits.length;\n    }\n    //Log("最大资产",maxAssets,"最大资产时间",_D(maxAssetsTime),"当前资产",profits[profits.length - 1][1],"当前资产时间",_D(profits[profits.length - 1][1]))\n    var nowDrawdown = 1 - (profits[profits.length - 1][1] + totalAssets) / maxAssets;\n    if (nowDrawdown < 0) {\n        nowDrawdown = 0;\n    }\n    // trim profits\n    var i = 0;\n    var datas = [];\n    var sum = 0;\n    var preProfit = 0;\n    var perRatio = 0;\n    var rangeEnd = te;\n    if ((te - ts) % period > 0) {\n        rangeEnd = (parseInt(te / period) + 1) * period;\n    }\n    for (var n = ts; n < rangeEnd; n += period) {\n        var dayProfit = 0.0;\n        var cut = n + period;\n        while (i < profits.length && profits[i][3] < cut) {\n            dayProfit += profits[i][1] - preProfit;\n            preProfit = profits[i][1];\n            i++;\n        }\n        perRatio = ((dayProfit / totalAssets) * yearRange) / period;\n        sum += perRatio;\n        datas.push(perRatio);\n    }\n\n    var sharpeRatio = 0;\n    var volatility = 0;\n    if (datas.length > 0) {\n        var avg = sum / datas.length;\n        var std = 0;\n        for (i = 0; i < datas.length; i++) {\n            std += Math.pow(datas[i] - avg, 2);\n        }\n        volatility = Math.sqrt(std / datas.length);\n        if (volatility !== 0) {\n            sharpeRatio = (annualizedReturns - freeProfit) / volatility;\n        }\n    }\n    return {\n        totalAssets: totalAssets,\n        yearDays: yearDays,\n        totalReturns: totalReturns,\n        annualizedReturns: annualizedReturns,\n        sharpeRatio: sharpeRatio,\n        volatility: volatility,\n        nowDrawdown: nowDrawdown,\n        maxDrawdown: maxDrawdown,\n        maxDrawdownTime: maxDrawdownTime,\n        maxAssetsTime: maxAssetsTime,\n        maxDrawdownStartTime: maxDrawdownStartTime,\n        winningRate: winningRate,\n        nowDrawdownFormat: $.TimeBetween(maxAssetsTime, new Date()),\n        maxDrawdownFormat: $.TimeBetween(maxDrawdownStartTime, maxDrawdownTime),\n    };\n};\n//取第多少周\n$.GetWeek = function (date) {\n    let nowDate = new Date(date);\n    let firstDay = new Date(date);\n    firstDay.setMonth(0); //设置1月\n    firstDay.setDate(1); //设置1号\n    let diffDays = Math.ceil((nowDate - firstDay) / (24 * 60 * 60 * 1000));\n    let week = Math.ceil(diffDays / 7);\n    week = week === 0 ? 1 : week;\n    let month = nowDate.getMonth() + 1;\n    if (month.toString().length == 1) {\n        month = "0" + month;\n    }\n    let ret = {\n        year: nowDate.getFullYear(),\n        month: month,\n        day: nowDate.getDate(),\n        week: week,\n    };\n    return ret;\n};\nfunction main() {}'

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
